/// <summary>
/// Bug 340986: E2E - Demand - CB201 - Post Provision Batch Job unsuccessful + Full Rebate Value = Write Off
/// </summary>
internal final class METTAMRebateContractHelper
{
}

Method.Source:
/// <summary>
/// Retrieve and update the TAMRebateTransactionType in the contract class
/// </summary>
/// <param name = "_container">container</param>
/// <param name = "_rebateTransactionType">TAMRebateTransactionType</param>
/// <returns>container</returns>
static container updateRebateTransactionTypeInPackedContract(container _container, TAMRebateTransactionType _rebateTransactionType)
{
    container packedContractContainer = conPeek(_container, 2);

    for (int i = 1; i <= conLen(packedContractContainer); i++)
    {
        container contractKeyValue = conPeek(packedContractContainer, i);

        if (conPeek(contractKeyValue, 1) == METConstants::parmRebateTransactionType)
        {
            contractKeyValue = conPoke(contractKeyValue, 2, enum2int(_rebateTransactionType));

            packedContractContainer = conPoke(packedContractContainer, i, contractKeyValue);
            _container = conPoke(_container, 2, packedContractContainer);
            break;
        }
    }

    return _container;
}
